from __future__ import annotations

import pathlib
import re
import sys


def get_characters():
    """Yield identifier characters not already matched by ``\\w``."""
    word_re = re.compile(r"\w", re.UNICODE)

    for codepoint in range(sys.maxunicode + 1):
        char = chr(codepoint)

        if word_re.match(char) is not None:
            continue

        if f"_{char}".isidentifier():
            yield char


def collapse_ranges(data):
    """Collapse a sorted iterable of characters into ordinal ranges."""
    iterator = iter(data)

    try:
        start = end = ord(next(iterator))
    except StopIteration:
        return

    for char in iterator:
        current = ord(char)

        if current == end + 1:
            end = current
            continue

        yield start, end
        start = end = current

    yield start, end


def build_pattern(ranges):
    """Build the character class used by ``src/jinja2/_identifier.py``."""

    def escape(value):
        return re.escape(chr(value))

    parts = []

    for start, end in ranges:
        if start == end:
            parts.append(escape(start))
        else:
            parts.append(f"{escape(start)}-{escape(end)}")

    return rf"[\w{''.join(parts)}]+"


def main() -> None:
    chars = sorted(set(get_characters()), key=ord)
    pattern = build_pattern(collapse_ranges(chars))
    root = pathlib.Path(__file__).resolve().parents[1]
    target = root / "src" / "jinja2" / "_identifier.py"
    target.write_text(
        "import re\n\n"
        "# generated by scripts/generate_identifier_pattern.py\n"
        "pattern = re.compile(\n"
        f'    r"{pattern}"  # noqa: B950\n'
        ")\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
